// Fixed drawing scripts for the canvas_ity vs Chromium canvas comparison
// matrix.  This file is the single source of truth for what gets drawn.
// Each case is written against the standard HTML5 Canvas 2D API; the
// recorder (record_ops.js) translates every call into an implementation-
// neutral op stream that is then replayed verbatim by both renderers:
//   - render_canvasity.cpp  (canvas_ity, C++)
//   - the Chromium headless page (Skia canvas, generated by make_page.js)
//
// Case categories: paths, strokes, gradients, text, transforms, clipping.
//
// Text cases use the embedded "CompareFont" (the test suite's FontA TTF,
// extracted from test/test.cpp by extract_font.js) so that both renderers
// shape the exact same outlines.  Glyphs available include: C D E F G H I
// a s t y z and the asterisk.

"use strict";

const W = 192;
const H = 192;

// Each case: { name, category, description, draw(ctx) }
const cases = [];

function def(name, category, description, draw) {
  cases.push({ name, category, description, width: W, height: H, draw });
}

// ---------------------------------------------------------------- paths ---

def("paths_polygon", "paths",
  "Filled concave polygon with solid color",
  (ctx) => {
    ctx.fillStyle = "#2a7fff";
    ctx.beginPath();
    ctx.moveTo(24, 24);
    ctx.lineTo(168, 40);
    ctx.lineTo(140, 96);
    ctx.lineTo(168, 160);
    ctx.lineTo(88, 140);
    ctx.lineTo(40, 168);
    ctx.lineTo(56, 96);
    ctx.closePath();
    ctx.fill();
  });

def("paths_star_winding", "paths",
  "Self-intersecting 5-point star, non-zero winding fill",
  (ctx) => {
    ctx.fillStyle = "rgba(220, 60, 40, 0.9)";
    ctx.beginPath();
    const cx = 96, cy = 100, r1 = 72, r2 = 30;
    for (let i = 0; i < 10; i++) {
      const r = i % 2 === 0 ? r1 : r2;
      const a = -Math.PI / 2 + (i * Math.PI) / 5;
      const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
  });

def("paths_bezier", "paths",
  "Closed shape built from cubic and quadratic curves",
  (ctx) => {
    ctx.fillStyle = "#18a058";
    ctx.beginPath();
    ctx.moveTo(32, 144);
    ctx.bezierCurveTo(32, 48, 160, 48, 160, 144);
    ctx.quadraticCurveTo(96, 112, 32, 144);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#0b3d24";
    ctx.beginPath();
    ctx.moveTo(64, 132);
    ctx.quadraticCurveTo(96, 60, 128, 132);
    ctx.quadraticCurveTo(96, 108, 64, 132);
    ctx.closePath();
    ctx.fill();
  });

def("paths_hole_and_arc", "paths",
  "Rect with reverse-wound rectangular hole, plus an arc pie slice",
  (ctx) => {
    ctx.fillStyle = "#7c3aed";
    ctx.beginPath();
    ctx.rect(24, 24, 88, 88);
    // reverse-wound inner rect punches a hole under non-zero winding
    ctx.moveTo(48, 48);
    ctx.lineTo(48, 88);
    ctx.lineTo(88, 88);
    ctx.lineTo(88, 48);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#f59e0b";
    ctx.beginPath();
    ctx.moveTo(128, 128);
    ctx.arc(128, 128, 44, 0.2, 2.6, false);
    ctx.closePath();
    ctx.fill();
  });

// --------------------------------------------------------------- strokes ---

def("strokes_widths", "strokes",
  "Straight lines at widths 1, 2.5 and 7 px",
  (ctx) => {
    ctx.strokeStyle = "#102030";
    const widths = [1, 2.5, 7];
    widths.forEach((w, i) => {
      ctx.lineWidth = w;
      ctx.beginPath();
      ctx.moveTo(24, 48 + i * 48);
      ctx.lineTo(168, 48 + i * 48);
      ctx.stroke();
    });
  });

def("strokes_caps_joins", "strokes",
  "Line caps (butt/round/square) and joins (miter/round/bevel)",
  (ctx) => {
    ctx.lineWidth = 12;
    ctx.strokeStyle = "#b91c1c";
    ["butt", "round", "square"].forEach((cap, i) => {
      ctx.lineCap = cap;
      ctx.beginPath();
      ctx.moveTo(40, 32 + i * 20);
      ctx.lineTo(152, 32 + i * 20);
      ctx.stroke();
    });
    ctx.strokeStyle = "#1d4ed8";
    ["miter", "round", "bevel"].forEach((join, i) => {
      ctx.lineJoin = join;
      ctx.beginPath();
      ctx.moveTo(40, 108 + i * 28);
      ctx.lineTo(96, 84 + i * 28);
      ctx.lineTo(152, 108 + i * 28);
      ctx.stroke();
    });
  });

def("strokes_dash", "strokes",
  "Dashed rectangle and dashed curve with dash offset",
  (ctx) => {
    ctx.strokeStyle = "#0f766e";
    ctx.lineWidth = 4;
    ctx.setLineDash([12, 6, 3, 6]);
    ctx.strokeRect(24, 24, 144, 80);
    ctx.lineDashOffset = 9;
    ctx.setLineDash([10, 5]);
    ctx.beginPath();
    ctx.moveTo(24, 160);
    ctx.bezierCurveTo(64, 110, 128, 210, 168, 140);
    ctx.stroke();
  });

def("strokes_miter_alpha", "strokes",
  "Miter limit clamp on a sharp corner; overlapping translucent strokes",
  (ctx) => {
    ctx.strokeStyle = "#334155";
    ctx.lineWidth = 10;
    ctx.lineJoin = "miter";
    ctx.miterLimit = 4;
    ctx.beginPath();
    ctx.moveTo(24, 60);
    ctx.lineTo(96, 52);
    ctx.lineTo(30, 66);
    ctx.stroke();
    ctx.lineJoin = "miter";
    ctx.miterLimit = 10;
    ctx.globalAlpha = 0.5;
    ctx.strokeStyle = "#dc2626";
    ctx.beginPath();
    ctx.arc(80, 136, 32, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.strokeStyle = "#2563eb";
    ctx.beginPath();
    ctx.arc(112, 136, 32, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.globalAlpha = 1;
  });

// -------------------------------------------------------------- gradients ---

def("gradients_linear", "gradients",
  "Two-stop horizontal linear gradient filling a rect",
  (ctx) => {
    const g = ctx.createLinearGradient(32, 0, 160, 0);
    g.addColorStop(0, "#ff0000");
    g.addColorStop(1, "#0000ff");
    ctx.fillStyle = g;
    ctx.fillRect(32, 48, 128, 96);
  });

def("gradients_linear_multi", "gradients",
  "Five-stop diagonal linear gradient with a mid offset stop",
  (ctx) => {
    const g = ctx.createLinearGradient(24, 24, 168, 168);
    g.addColorStop(0, "#000000");
    g.addColorStop(0.25, "#ff00ff");
    g.addColorStop(0.5, "#ffff00");
    g.addColorStop(0.75, "#00ffff");
    g.addColorStop(1, "#ffffff");
    ctx.fillStyle = g;
    ctx.fillRect(24, 24, 144, 144);
  });

def("gradients_radial", "gradients",
  "Radial gradient (offset focal circle) filling a circle",
  (ctx) => {
    const g = ctx.createRadialGradient(84, 84, 8, 96, 96, 72);
    g.addColorStop(0, "#ffffff");
    g.addColorStop(0.6, "#f97316");
    g.addColorStop(1, "rgba(30, 27, 75, 0.85)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(96, 96, 72, 0, 2 * Math.PI);
    ctx.fill();
  });

def("gradients_transformed", "gradients",
  "Gradient fill under rotation; gradient used as a stroke style",
  (ctx) => {
    const g = ctx.createLinearGradient(-40, 0, 40, 0);
    g.addColorStop(0, "#06b6d4");
    g.addColorStop(1, "#8b5cf6");
    ctx.fillStyle = g;
    ctx.save();
    ctx.translate(96, 64);
    ctx.rotate(Math.PI / 6);
    ctx.fillRect(-48, -24, 96, 48);
    ctx.restore();
    const g2 = ctx.createLinearGradient(24, 0, 168, 0);
    g2.addColorStop(0, "#111827");
    g2.addColorStop(1, "#22d3ee");
    ctx.strokeStyle = g2;
    ctx.lineWidth = 14;
    ctx.beginPath();
    ctx.moveTo(32, 150);
    ctx.lineTo(160, 122);
    ctx.stroke();
  });

// ------------------------------------------------------------------- text ---

def("text_fill_sizes", "text",
  "Filled text at several sizes (CompareFont)",
  (ctx) => {
    ctx.fillStyle = "#111111";
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.font = "36px CompareFont";
    ctx.fillText("HIty", 16, 52);
    ctx.font = "24px CompareFont";
    ctx.fillText("CEaI", 16, 104);
    ctx.font = "14px CompareFont";
    ctx.fillText("styasy", 16, 148);
  });

def("text_align_baseline", "text",
  "Text alignment (left/center/right) and baselines against rules",
  (ctx) => {
    ctx.strokeStyle = "#cccccc";
    ctx.lineWidth = 1;
    [48, 96, 144].forEach((y) => {
      ctx.beginPath(); ctx.moveTo(8, y); ctx.lineTo(184, y); ctx.stroke();
    });
    ctx.beginPath(); ctx.moveTo(96, 16); ctx.lineTo(96, 176); ctx.stroke();
    ctx.fillStyle = "#9d174d";
    ctx.font = "22px CompareFont";
    ctx.textBaseline = "alphabetic";
    ctx.textAlign = "left";
    ctx.fillText("HI", 96, 48);
    ctx.textAlign = "center";
    ctx.fillText("HI", 96, 96);
    ctx.textAlign = "right";
    ctx.fillText("HI", 96, 144);
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("ty", 48, 48);
    ctx.textBaseline = "top";
    ctx.fillText("ty", 144, 96);
    ctx.textBaseline = "bottom";
    ctx.fillText("ty", 48, 144);
  });

def("text_stroke", "text",
  "Stroked text outline over a filled ghost",
  (ctx) => {
    ctx.font = "44px CompareFont";
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.fillStyle = "rgba(37, 99, 235, 0.25)";
    ctx.fillText("HIty", 24, 110);
    ctx.strokeStyle = "#1e3a8a";
    ctx.lineWidth = 1.5;
    ctx.strokeText("HIty", 24, 110);
  });

def("text_transformed", "text",
  "Text drawn under rotation and non-uniform scale",
  (ctx) => {
    ctx.fillStyle = "#065f46";
    ctx.font = "26px CompareFont";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.save();
    ctx.translate(96, 64);
    ctx.rotate(-Math.PI / 8);
    ctx.fillText("HIty", 0, 0);
    ctx.restore();
    ctx.save();
    ctx.translate(96, 140);
    ctx.scale(1.5, 0.75);
    ctx.fillText("CEI", 0, 0);
    ctx.restore();
  });

// ------------------------------------------------------------- transforms ---

def("transform_compose", "transforms",
  "translate/rotate/scale composition over nested squares",
  (ctx) => {
    ctx.fillStyle = "#0ea5e9";
    ctx.fillRect(76, 76, 40, 40);
    ctx.translate(96, 96);
    ctx.rotate(Math.PI / 4);
    ctx.fillStyle = "rgba(244, 63, 94, 0.75)";
    ctx.fillRect(-30, -30, 60, 60);
    ctx.scale(0.6, 0.6);
    ctx.rotate(Math.PI / 4);
    ctx.fillStyle = "rgba(250, 204, 21, 0.85)";
    ctx.fillRect(-30, -30, 60, 60);
  });

def("transform_matrix", "transforms",
  "setTransform with a skew matrix, then a transform() multiply",
  (ctx) => {
    ctx.setTransform(1, 0.25, -0.35, 1, 96, 32);
    ctx.fillStyle = "#4d7c0f";
    ctx.fillRect(-24, 0, 48, 48);
    ctx.transform(1, 0, 0.2, 0.8, 0, 48);
    ctx.fillStyle = "#9333ea";
    ctx.fillRect(-24, 0, 48, 48);
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = "#111111";
    ctx.fillRect(8, 8, 8, 8);
  });

def("transform_save_restore", "transforms",
  "Nested save/restore scopes with independent transforms",
  (ctx) => {
    ctx.fillStyle = "#1f2937";
    ctx.save();
    ctx.translate(48, 48);
    ctx.fillRect(-16, -16, 32, 32);
    ctx.save();
    ctx.translate(96, 0);
    ctx.rotate(Math.PI / 3);
    ctx.fillStyle = "#be185d";
    ctx.fillRect(-16, -16, 32, 32);
    ctx.restore();
    ctx.translate(0, 96);
    ctx.scale(2, 0.5);
    ctx.fillStyle = "#0d9488";
    ctx.fillRect(-16, -16, 32, 32);
    ctx.restore();
    ctx.fillRect(140, 140, 24, 24);
  });

def("transform_path_space", "transforms",
  "Path coordinates captured under a transform, stroked after another",
  (ctx) => {
    ctx.save();
    ctx.translate(96, 96);
    ctx.rotate(Math.PI / 5);
    ctx.beginPath();
    ctx.moveTo(-60, 0);
    ctx.lineTo(0, -40);
    ctx.lineTo(60, 0);
    ctx.lineTo(0, 40);
    ctx.closePath();
    ctx.restore(); // stroke with identity: path keeps transformed coords
    ctx.fillStyle = "#0369a1";
    ctx.fill();
    ctx.strokeStyle = "#f0abfc";
    ctx.lineWidth = 3;
    ctx.stroke();
  });

// --------------------------------------------------------------- clipping ---

def("clip_rect", "clipping",
  "Rectangular clip region over a full-bleed fill",
  (ctx) => {
    ctx.save();
    ctx.beginPath();
    ctx.rect(40, 40, 112, 112);
    ctx.clip();
    ctx.fillStyle = "#ea580c";
    ctx.fillRect(0, 0, 192, 192);
    ctx.fillStyle = "#164e63";
    ctx.fillRect(0, 96, 192, 96);
    ctx.restore();
  });

def("clip_circle_gradient", "clipping",
  "Circular clip over a linear gradient fill",
  (ctx) => {
    ctx.save();
    ctx.beginPath();
    ctx.arc(96, 96, 64, 0, 2 * Math.PI);
    ctx.clip();
    const g = ctx.createLinearGradient(32, 32, 160, 160);
    g.addColorStop(0, "#fde047");
    g.addColorStop(1, "#be123c");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 192, 192);
    ctx.restore();
  });

def("clip_nested", "clipping",
  "Intersecting nested clips across save/restore scopes",
  (ctx) => {
    ctx.fillStyle = "#e5e7eb";
    ctx.fillRect(0, 0, 192, 192);
    ctx.save();
    ctx.beginPath();
    ctx.rect(32, 32, 128, 128);
    ctx.clip();
    ctx.save();
    ctx.beginPath();
    ctx.arc(120, 120, 64, 0, 2 * Math.PI);
    ctx.clip();
    ctx.fillStyle = "#2563eb";
    ctx.fillRect(0, 0, 192, 192);
    ctx.restore();
    ctx.fillStyle = "rgba(22, 163, 74, 0.8)";
    ctx.fillRect(0, 0, 192, 192);
    ctx.restore();
  });

def("clip_path_text", "clipping",
  "Text and strokes drawn through a star-shaped clip",
  (ctx) => {
    ctx.save();
    ctx.beginPath();
    const cx = 96, cy = 96;
    for (let i = 0; i < 10; i++) {
      const r = i % 2 === 0 ? 80 : 36;
      const a = -Math.PI / 2 + (i * Math.PI) / 5;
      const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.clip();
    ctx.fillStyle = "#f8fafc";
    ctx.fillRect(0, 0, 192, 192);
    ctx.fillStyle = "#0f172a";
    ctx.font = "40px CompareFont";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("HIty", 96, 100);
    ctx.strokeStyle = "#dc2626";
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(16, 32);
    ctx.lineTo(176, 160);
    ctx.stroke();
    ctx.restore();
  });

module.exports = { cases, W, H };
